function stageEditor(id){const r=plan().rules.find(r=>r.id===id);modal('変更する月と金額',`<h3>${esc(r.name)}</h3><p class="hint">この月以降の予定を変更します．同じ項目なので，重ねて足されません．年度別の金額がある年度は，年度別入力が優先です．</p>`+(r.changes||[]).map(c=>`<p class="hint">${c.month}から ${money(c.amount)}／月 ${esc(c.label||'')}</p>`).join('')+input('変更する月','month',selectedMonth,'month','required')+amount('変更後の月額（円）','amount','','required min="0"')+input('変更のメモ','label','','text','placeholder="例：転職，年金，家賃変更"'),f=>{const m=f.get('month');r.changes=r.changes.filter(c=>c.month!==m);r.changes.push({month:m,amount:U.N(f.get('amount')),label:f.get('label')});persist('変更月：'+r.name);});}
function yearsPage(){const [type,id]=section.split(':'),r=(type==='childyears'?plan().children:plan().rules).find(x=>x.id===id);if(!r){section='';return planPage();}const start=U.fy(note().start),values=type==='childyears'?r.years:r.annualYears;return breadcrumb(esc(r.name)+'：年度別の金額')+notice('4月から翌年3月までの年間金額です．入力した年度は，この金額÷12を月予定へ使います．空欄に戻すと基本の予定へ戻ります．退職金など1回だけのお金は「時々のお金」に年月を指定して入れます．')+`<div class="actions">${button('複数年度をまとめて入力','year-fill',id)}${type==='years'?button('退職金・臨時収入を追加','retirement',id):''}</div><div class="card"><div class="scroll" tabindex="0" aria-label="年度別の年間金額"><table><thead><tr><th>年度</th><th>年間金額・円</th><th>月あたり</th></tr></thead><tbody>${Array.from({length:periodYears()},(_,i)=>start+i).map(y=>`<tr><th>${y}年度</th><td><input aria-label="${y}年度の年間金額" data-annual="${y}" data-owner="${esc(id)}" data-type="${type}" type="text" data-money min="0" inputmode="decimal" placeholder="基本の予定を使用" value="${esc(num(values?.[y]))}"></td><td data-annual-preview="${y}">${values?.[y]!==undefined&&values[y]!==null&&values[y]!==''?money(values[y]/12):'基本の予定'}</td></tr>`).join('')}</tbody></table></div></div>`;}
function eventsPage(){const p=plan(),events=p.events.filter(e=>!e.sinking),once=events.filter(e=>U.N(e.every)<=0),repeat=events.filter(e=>U.N(e.every)>0),sinking=p.events.filter(e=>e.sinking),savings=p.rules.filter(r=>r.kind==='reserve'),sort=rows=>rows.slice().sort((a,b)=>a.month.localeCompare(b.month)),eventRows=rows=>sort(rows).map(e=>compactRow('eventsPage:'+e.id,`<span><b>${esc(e.name)}</b><small>${e.month} ／ ${label[e.kind]}${e.every?' ／ '+X.formatDuration(e.every)+'ごと':''}${e.end?' ／ '+e.end+'まで':''}${e.enabled===false?' ／ 予定から除外':''}${e.useReserve?' ／ 別枠貯金から支払う':''}</small>${money(e.amount)}</span>`,`${button('月・金額を変更','event-edit',e.id)}${button('複製','event-copy',e.id)}${button('削除','event-delete',e.id,'text-button danger')}`)).join(''),group=(key,title,count,hint,body)=>`<details class="card event-category" data-keep="events-category:${key}"><summary><span><b>${title}</b><small>${hint}</small></span><span class="event-count">${count}件</span></summary><div class="event-category-body">${body}</div></details>`;
return breadcrumb('時々のお金')+'<p class="sub">まず，予定の種類を選んでください．種類を開くと，登録済みの予定と追加ボタンが表示されます．</p>'+group('once','一回きり',once.length,'旅行・結婚・引越しなど，指定した月に1回',`<div class="actions">${button('一回きりの予定を追加','event-new','','primary')}</div>${eventRows(once)||empty('一回きりの予定はまだありません．')}`)+group('repeat','周期的',repeat.length,'記念日など，毎年・数か月ごとの予定',`<div class="actions">${button('周期的な予定を追加','event-new-repeat','','primary')}</div>${eventRows(repeat)||empty('周期的な予定はまだありません．')}`)+group('funds','用途別の積立・買替',sinking.length+savings.length,'家電の買替など，目的を決めて積み立てる予定',`<p class="hint">全体の案で採用中の用途別積立を表示しています．</p><div class="actions">${button('積立・買替を追加','event-sinking-new','','primary')}${button('毎月の積立・用途を管理','event-funds')}</div>${sort(sinking).map(e=>compactRow('events-sinking:'+e.id,`<span><b>${esc(e.name)}</b><small>積立開始 ${e.month} ／ ${X.formatDuration(e.every)}ごと${e.enabled===false?' ／ 予定から除外':''}</small>購入 ${money(e.amount)}</span>`,`<p class="hint">毎月 ${money(e.deposit==null?e.amount/e.every:e.deposit)}を積立 ／ ${esc(note().purposes?.find(f=>f.id===e.fundId)?.name||'用途未分類')}</p>${button('月・金額・用途を変更','event-fund-edit',e.id)}`)).join('')}${savings.map(r=>compactRow('events-saving:'+r.id,`<span><b>${esc(r.name)}</b><small>毎月の積立 ／ ${r.start}から${r.end?' ／ '+r.end+'まで':''}</small>${money(U.ruleAmount(r,selectedMonth,p))}</span>`,button('毎月の積立を管理','event-funds'))).join('')}${!sinking.length&&!savings.length?empty('用途別の積立・買替はまだありません．'):''}`);}
function eventEditor(id,retirement=false,repeatEvery=0){const e=plan().events.find(e=>e.id===id)||{id:U.uid(),name:retirement?'退職金':'',month:selectedMonth,kind:retirement?'income':'expense',amount:'',every:repeatEvery,end:'',enabled:true};modal(id?'イベントの月・金額を変更':'イベントを追加',input('イベント名','name',e.name,'text','required maxlength="60" placeholder="例：旅行，賞与，退職金"')+select('お金の動き','kind',[['expense','特別支出'],['income','特別収入']],e.kind)+input('発生する年月','month',e.month,'month','required')+amount('金額（円）','amount',e.amount,'required min="0"')+select('繰り返し','repeatMode',[[0,'1回だけ'],[1,'繰り返す']],e.every?1:0)+duration('繰り返す場合の間隔','every',e.every||12)+input('繰り返しの終了月（任意）','end',e.end,'month')+check('このイベントを予定に含める','enabled',e.enabled!==false)+check('支出は別枠貯金から支払う（不足分は現金から）','useReserve',e.useReserve)+select('別枠貯金から支払う場合の用途','fundId',[['general','用途未分類'],...(note().purposes||[]).map(f=>[f.id,f.name])],e.fundId||'general')+notice('変更するのは予定です．旧月に記録済みの実績は，その月に残ります．'),f=>{const v=Object.fromEntries(f);if(v.end&&v.end<v.month)throw Error('終了月は発生月以降にしてください．');Object.assign(e,{name:v.name.trim(),month:v.month,kind:v.kind,amount:U.N(v.amount),every:f.has('repeatMode')?(v.repeatMode==='0'?0:readDuration(f,'every')):U.N(v.every),end:v.end,enabled:f.has('enabled'),fundId:v.fundId||'general',useReserve:v.kind==='expense'&&f.has('useReserve')});if(!e.name)throw Error('名前を入力してください．');if(!id)plan().events.push(e);persist('イベント：'+e.name);section='events';route='plan';});}
