function budgetPage(){const p=plan(),b=p.budgets[year];return breadcrumb('当初予算をまとめて決める')+notice('当初予算は，そのときの目標として残す金額です．あとから予定やイベントを増やしても，自動では変わりません．金額は月ごとに手入力できます．')+`<div class="actions">${button('今の予定を全年度まとめて保存','budget-capture-all','','primary')}${button('金額を決めて複数年度に入力','budget-fill')}</div>`+yearSelect()+`<details class="secondary-tools"><summary>表示中の年度だけ保存する</summary><div class="actions">${button(b?'今の予定で当初予算を更新':'今の予定を当初予算として残す','capture-budget','','primary')}</div></details><p class="hint">${b?'設定日時：'+new Date(b.at).toLocaleString('ja-JP'):'未設定です．空欄のままなら，0円の予算とは扱いません．'} ／ 表は左右にスクロールできます．</p><div class="card"><div class="scroll" tabindex="0"><table><thead><tr><th>月</th>${U.kinds.map(k=>'<th>'+label[k]+'・円</th>').join('')}</tr></thead><tbody>${Array.from({length:12},(_,i)=>U.month(year,(i+3)%12+1)).filter(m=>m>=note().start).map(m=>`<tr><th>${m}</th>${U.kinds.map(k=>`<td><input aria-label="${m}の当初予算${label[k]}" data-budget="${m}" data-kind="${k}" type="text" data-money inputmode="decimal" min="0" placeholder="未設定" value="${esc(num(b?.months?.[m]?.[k]))}"></td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`;}
function conditionsPage(){const p=plan();return breadcrumb('長期の条件・年度別の収入')+`<div class="card"><h2>本人・パートナーの収入とパターン</h2><div class="actions">${button('本人・パートナーのパターン一覧','to-income')}</div><p class="sub">毎月の収入と同じ項目です．年度別金額を入れた年は，その年の月額を置き換えます．二重に加算しません．</p>${p.rules.filter(r=>r.kind==='income').map(r=>compactRow('condition-income:'+r.id,`<b>${esc(r.name)}</b>`,`${r.patterns?.length?button('パターンと切替','patterns',r.id):r.kind==='income'?button('働き方パターン','patterns',r.id):''}${!r.patternType||r.patternType!=='living'?button('年度別に入力','rule-years',r.id):''}`)).join('')||empty('先に「毎月のお金」で収入の項目を作ってください．')}${button('収入などの項目を追加','rule-new')}</div><form id="conditionsForm" class="card"><h2>見通しの範囲と仮定</h2><p class="hint">率は空欄なら0％で計算します．未入力の率を勝手に設定しません．</p><p class="notice">計算と年度一覧は2100年度までです．グラフは2065年度までを標準とし，2100年度までの表示へ切り替えられます．</p>${amount('物価の年変化率（％）','inflation',p.inflation,'min="-100" max="100"')}${amount('投資の想定年利（％）','returnRate',p.returnRate,'min="-100" max="100"')}<p class="hint">物価は「物価を反映する」を選んだ月予定だけに適用します．運用益は月初の投資残高に年利の月換算率を掛けて試算します．税・手数料・NISA制度上限は自動判定しません．投資の予定額は実際に積み立てられる額で入力してください．</p><button class="primary" type="submit">条件を保存する</button></form>`;}
function branchesPage(){const n=note();return breadcrumb('別の案を作る')+notice('コピーするのは予定と長期条件です．入力済みの実績・開始残高は全ての案で同じものを使います．イベントや月額を変えても，元の案は残ります．')+`<div class="actions">${button('今の案から分岐する','branch','','primary')}${button('先の見通しで比較する','to-outlook')}</div><div class="card">${Object.values(n.plans).map(p=>compactRow('branchesPage:'+p.id,`<span><b>${esc(p.name)} ${p.id===n.activePlan?'<span class="badge">選択中</span>':''}</b><small>${p.parentId?'分岐元：'+esc(n.plans[p.parentId]?.name||'削除済み'):'最初の案'}</small></span>`,`${button('名前を変更','rename',p.id)}${button('削除','plan-delete',p.id,'danger')}${button('この案を開く','use-plan',p.id)}`)).join('')}</div>`;}
function chartBounds(){const first=U.fy(note().start);chartCustomStart=Math.max(first,Math.min(2100,chartCustomStart??first));chartCustomEnd=Math.max(chartCustomStart,Math.min(2100,chartCustomEnd??Math.max(first,workEndYear)));return chartRange==='custom'?[chartCustomStart,chartCustomEnd]:[first,chartRange==='life'?2100:Math.max(first,workEndYear)];}
