function chartPeriodControls(){const [from,to]=chartBounds(),options=Array.from({length:2100-U.fy(note().start)+1},(_,i)=>U.fy(note().start)+i),picker=(id,title,value)=>`<label>${title}<select id="${id}" aria-label="${title}">${options.map(y=>`<option value="${y}" ${y===value?'selected':''}>${y}年度</option>`).join('')}</select></label>`;return `<div class="chart-period"><label>グラフの表示期間<select id="chartRange" aria-label="グラフの表示期間"><option value="work" ${chartRange==='work'?'selected':''}>${workEndYear}年度まで（仕事終わりまで）</option><option value="life" ${chartRange==='life'?'selected':''}>2100年度まで</option><option value="custom" ${chartRange==='custom'?'selected':''}>カスタム</option></select></label>${chartRange==='work'?button('仕事終わりの年度を変更','chart-work-year'):''}</div>${chartRange==='custom'?`<div class="chart-custom-period">${picker('chartCustomStart','開始年度',from)}${picker('chartCustomEnd','終了年度',to)}</div>`:''}`;}
