function masterPage(){const labels=Object.keys(master.ages?.[0]||{});return breadcrumb('教育費マスタの確認・編集')+notice('v1で使っていた基礎データを残しています．金額は年間額です．この案の上書きだけを保存し，基礎データは消しません．子どもの「マスタを使う」にチェックした場合に適用します．')+notice('大学院生の費用には生活費も含まれています．大学卒業後に就職する場合は生活費を入れないため，同じ年齢でも，大学院へ進学するか就職するかによって生活費を計上するかどうかが異なります．')+select('表示・編集する項目','masterColumn',labels.map(s=>[s,s]),masterColumn)+`<div class="actions">${button('マスタをJSONに書き出す','master-export')}${button('マスタのJSONを取り込む','master-import')}</div><div class="card"><div class="scroll" tabindex="0"><table><thead><tr><th>年齢</th><th>基礎データ</th><th>この案の上書き・円</th><th>適用額</th></tr></thead><tbody>${Object.entries(master.ages).map(([age,row])=>`<tr><th>${age}歳</th><td>${money(row[masterColumn])}</td><td><input aria-label="${age}歳の${esc(masterColumn)}" type="text" data-money inputmode="decimal" min="0" data-master-age="${age}" data-master-key="${esc(masterColumn)}" value="${esc(num(plan().masterOverrides?.[age]?.[masterColumn]))}" placeholder="基礎データを使用"></td><td data-master-preview="${age}">${money(plan().masterOverrides?.[age]?.[masterColumn]??row[masterColumn])}</td></tr>`).join('')}</tbody></table></div></div>`;}
function educationAnnual(){const children=plan().children;if(!children.length)return '';const start=U.fy(note().start);return '<details class="card education-annual" data-keep="education-annual:'+esc(sourceContext?.id||wholePlan().id)+'"><summary>年度ごとの内訳</summary><p class="hint">この教育案の全員の合計と，1人ずつの年間額です．年度を開くと費用の内訳を確認できます．</p>'+Array.from({length:periodYears()},(_,i)=>start+i).map(y=>{const rows=children.map(c=>({c,d:U.childDetail(c,y,master,plan().masterOverrides)})),total=rows.reduce((sum,r)=>sum+r.d.amount,0);return U.listUI.row('education-total:'+sourceContext?.id+':'+y,'<span><b>'+y+'年度　合計 '+money(total)+'</b><small>'+rows.map(r=>esc(r.c.name)+' '+money(r.d.amount)).join(' ／ ')+'</small></span>',rows.map(({c,d})=>'<section class="education-child-detail"><h3>'+esc(c.name)+'：'+money(d.amount)+'</h3><p class="hint">'+(d.age<0?'出生前':d.age+'歳')+' ／ '+esc(d.reason)+' ／ 月 '+money(d.amount/12)+'</p>'+d.parts.map(i=>'<div class="list-row"><span>'+esc(i.name)+'</span><b>'+money(i.amount)+'</b></div>').join('')+'</section>').join(''));}).join('')+'</details>';}
