function housingRenewalEditor(key){const{r,p,c}=housingRenewal(key),v=c||{id:U.uid(),name:'更新料',amount:null,every:24,fundId:'',autoSaving:true};modal('住居費の更新・定期支払い',input('支払う費用の名前','name',v.name,'text','required maxlength="60"')+amount('1回の支払額','amount',v.amount,'required min="0"')+duration('入居から初回支払いまで・以後の間隔','every',v.every)+check('必要な期間に住居更新料を自動積立する','autoSaving',v.autoSaving!==false)+'<details class="secondary-tools"><summary>自動積立を使わない場合の支払元</summary>'+select('支払うお金','fundId',[['','現金から支払う'],...(note().purposes||[]).map(f=>[f.id,f.name])],v.fundId||'')+'</details>'+notice('金額と周期を保存すると用途別積立も自動で用意します．入居月と住み替え月から，更新料を支払う予定がある期間だけ積み立てます．従来の年額（月割）に同じ費用を含めている場合は，その分を除いてください．'),f=>{const name=f.get('name').trim(),value=U.N(f.get('amount')),every=readDuration(f,'every'),fundId=f.get('fundId')||'',autoSaving=f.has('autoSaving');if(!name||!Number.isFinite(value)||value<0)throw Error('費用名と0円以上の金額を入力してください．');if(fundId&&!(note().purposes||[]).some(x=>x.id===fundId))throw Error('支払う用途を選び直してください．');let target=fundId;if(autoSaving){let fund=(note().purposes||[]).find(f=>f.name==='住居更新料');if(!fund){fund={id:U.uid(),name:'住居更新料',initial:0,autoHousing:true};(note().purposes||=[]).push(fund);}target=fund.id;}const row={...v,name,amount:value,every,fundId:target,autoSaving};if(c)Object.assign(c,row);else(p.renewals||=[]).push(row);persist('住居費の支払予定：'+name);});}

function housingRenewalFund(key){const{r,p,c}=housingRenewal(key);if(!c)throw Error('先に支払予定を登録してください．');const n=note(),q=n.categoryCatalog.funds.find(q=>q.id===wholePlan().categorySelections.funds),link={ruleId:r.id,profileId:p.id,costId:c.id},existing=q.rules.find(x=>JSON.stringify(x.housingLink)===JSON.stringify(link)),fund=existing?.fundId||c.fundId||'new',start=existing?.start||U.planning.periods(r,p.id)[0]?.from||selectedMonth;modal('住居更新料の用途別積立',notice('積立先の案：'+esc(q.name)+'．この積立案を使う全体プランに反映します．支出は住居費だけに計上し，積立から充当します．この住居を使う月だけ積み立て，住み替え後は停止します．')+select('積立の用途','fundId',[['new','新しく「住居更新料」を作る'],...(n.purposes||[]).map(f=>[f.id,f.name])],fund)+amount('毎月の積立額', 'amount',existing?.amount??Math.ceil(c.amount/c.every),'required min="0"')+input('積立開始月','start',start,'month','required')+notice('初期値は支払額÷周期を1円単位で切り上げた額です．最初の支払いまでの期間が短い場合は，積立額や開始残高を調整できます．不足分は現金から支払います．'),f=>{const value=U.N(f.get('amount')),month=f.get('start');let fundId=f.get('fundId');if(value<0||!U.validMonth(month))throw Error('積立額と開始月を確認してください．');if(fundId==='new'){const already=(n.purposes||[]).find(x=>x.name==='住居更新料');if(already)fundId=already.id;else{fundId=U.uid();(n.purposes||=[]).push({id:fundId,name:'住居更新料',initial:0});}}else if(!(n.purposes||[]).some(x=>x.id===fundId))throw Error('積立先を選び直してください．');c.fundId=fundId;c.autoSaving=false;const row={...(existing||{id:U.uid(),changes:[],annualYears:{},end:''}),name:'住居更新料・'+p.name+'・'+c.name,kind:'reserve',group:'用途別積立',fundId,amount:value,start:month,housingLink:link};if(existing)Object.assign(existing,row);else q.rules.push(row);persist('住居更新料の用途別積立');enterSource('housing',sourceContext.id);});}
